package app.flare.auto;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;
public final class CustomizeActivity extends Activity {
 UiKit ui;SharedPreferences prefs;HomeActivity home;LinearLayout root,body,preview,row;FrameLayout leftBox,rightBox;TextView hint,appsButton;View handle;int split;final int[] location=new int[2];final StringBuilder hintText=new StringBuilder(32);String left,right;static final String[] TYPES={"clock","media","apps","hidden"},LABELS={"Clock","Media","Applications","Hidden"};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(UiFlags.IMMERSIVE);ui=new UiKit(this);getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(ui.t.background));prefs=getSharedPreferences("home",0);home=HomeActivity.instance.get();left=HomeActivity.card(prefs,true);right=HomeActivity.card(prefs,false);split=Math.max(35,Math.min(65,prefs.getInt("split",58)));render();}
 void render(){if(root==null){root=ui.column();root.setBackgroundColor(ui.t.background);root.addView(ui.header("Home layout"),new LinearLayout.LayoutParams(-1,ui.dp(56)));body=ui.column();root.addView(body,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);if(home==null||home.isFinishing()||home.isDestroyed()){body.addView(ui.text("Open Home, then return to this editor",16,ui.t.textSecondary));return;}preview=new LinearLayout(this);preview.setOrientation(LinearLayout.HORIZONTAL);preview.setPadding(ui.dp(12),ui.dp(8),ui.dp(12),ui.dp(8));preview.setBackground(WallpaperPack.home(this,ui.t));body.addView(preview,new LinearLayout.LayoutParams(-1,0,1));hint=ui.text("",14,ui.t.textSecondary);hint.setGravity(Gravity.CENTER);hint.setMinHeight(ui.dp(36));body.addView(hint);row=new LinearLayout(this);row.setGravity(Gravity.CENTER);body.addView(row,new LinearLayout.LayoutParams(-1,ui.dp(56)));button("Swap sides",()->{String x=left;left=right;right=x;save();});button("Left card",()->choose(true));button("Right card",()->choose(false));button("Reset",()->new ThemedDialogs.Builder(this).setTitle("Reset layout?").setPositiveButton("Reset",(d,w)->{prefs.edit().remove("layout_left").remove("layout_right").remove("split").remove("projection").remove("media").apply();left="clock";right="media";split=58;render();}).setNegativeButton("Cancel",null).show());appsButton=ui.text("Manage applications",16,ui.t.accent);appsButton.setGravity(Gravity.CENTER);appsButton.setMinHeight(ui.dp(56));appsButton.setOnClickListener(v->editApps());body.addView(appsButton);}if(preview==null)return;preview.removeAllViews();boolean showLeft=!left.equals("hidden"),showRight=!right.equals("hidden");if(showLeft){leftBox=cardBox(left);preview.addView(leftBox,new LinearLayout.LayoutParams(0,-1,showRight?split:1));}else leftBox=null;if(showLeft&&showRight){handle=ui.text("⋮",22,ui.t.textSecondary);((TextView)handle).setGravity(Gravity.CENTER);preview.addView(handle,new LinearLayout.LayoutParams(ui.dp(40),-1));handle.setOnTouchListener((v,e)->drag(e));}if(showRight){rightBox=cardBox(right);preview.addView(rightBox,new LinearLayout.LayoutParams(0,-1,showLeft?100-split:1));}else rightBox=null;appsButton.setVisibility(left.equals("apps")||right.equals("apps")?View.VISIBLE:View.GONE);updateHint();}
 FrameLayout cardBox(String type){FrameLayout frame=new FrameLayout(this);LinearLayout card=home.makeCardPreview(type);frame.addView(card,new FrameLayout.LayoutParams(-1,-1));View inert=new View(this);inert.setOnTouchListener((v,e)->true);frame.addView(inert,new FrameLayout.LayoutParams(-1,-1));return frame;}
 boolean drag(android.view.MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:preview.requestDisallowInterceptTouchEvent(true);return true;case MotionEvent.ACTION_MOVE:preview.getLocationOnScreen(location);int width=preview.getWidth()-preview.getPaddingLeft()-preview.getPaddingRight()-handle.getWidth();if(width>0){int n=Math.max(35,Math.min(65,(int)((e.getRawX()-location[0]-preview.getPaddingLeft()-handle.getWidth()/2f)*100/width)));if(n!=split){split=n;((LinearLayout.LayoutParams)leftBox.getLayoutParams()).weight=split;((LinearLayout.LayoutParams)rightBox.getLayoutParams()).weight=100-split;leftBox.requestLayout();rightBox.requestLayout();updateHint();}}return true;case MotionEvent.ACTION_UP:prefs.edit().putInt("split",split).apply();preview.requestDisallowInterceptTouchEvent(false);return true;case MotionEvent.ACTION_CANCEL:split=Math.max(35,Math.min(65,prefs.getInt("split",58)));((LinearLayout.LayoutParams)leftBox.getLayoutParams()).weight=split;((LinearLayout.LayoutParams)rightBox.getLayoutParams()).weight=100-split;leftBox.requestLayout();rightBox.requestLayout();updateHint();preview.requestDisallowInterceptTouchEvent(false);return true;default:return true;}}
 void updateHint(){hintText.setLength(0);if(leftBox!=null&&rightBox!=null)hintText.append("Drag divider   ").append(split).append("% / ").append(100-split).append('%');else hintText.append("Choose a card for each side");hint.setText(hintText);}
 void button(String label,Runnable action){TextView b=ui.text(label,14,ui.t.textPrimary);b.setGravity(Gravity.CENTER);b.setMinimumHeight(ui.dp(56));row.addView(b,new LinearLayout.LayoutParams(0,ui.dp(56),1));b.setOnClickListener(v->action.run());}
 void choose(boolean isLeft){new ThemedDialogs.Builder(this).setTitle(isLeft?"Left card":"Right card").setItems(LABELS,(d,n)->{String value=TYPES[n];if(!value.equals("hidden")&&!value.equals("apps")&&value.equals(isLeft?right:left)){Toast.makeText(this,"That card is already in use",Toast.LENGTH_SHORT).show();return;}if(isLeft)left=value;else right=value;save();}).show();}
 void save(){prefs.edit().putString("layout_left",left).putString("layout_right",right).apply();render();}
 void editApps(){try{JSONArray a=new JSONArray(prefs.getString("layout_apps","[]"));String[] options=new String[a.length()+1];options[0]=a.length()<8?"Add app":"8 apps maximum";for(int i=0;i<a.length();i++){String target=a.getString(i);try{options[i+1]="Remove "+getPackageManager().getActivityInfo(ComponentName.unflattenFromString(target),0).loadLabel(getPackageManager());}catch(Exception e){options[i+1]="Remove unavailable app";}}new ThemedDialogs.Builder(this).setTitle("App shortcuts").setItems(options,(d,n)->{if(n==0){if(a.length()<8)startActivityForResult(new Intent(this,AppPickerActivity.class).putExtra(AppPickerActivity.ROLE,"layout"),1);}else{JSONArray next=new JSONArray();for(int j=0;j<a.length();j++)if(j!=n-1)next.put(a.optString(j));prefs.edit().putString("layout_apps",next.toString()).apply();render();}}).show();}catch(JSONException ignored){}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==1&&result==RESULT_OK&&data!=null){String target=data.getStringExtra(AppPickerActivity.TARGET);if(target==null||target.isEmpty())return;try{JSONArray a=new JSONArray(prefs.getString("layout_apps","[]"));if(a.length()<8){a.put(target);prefs.edit().putString("layout_apps",a.toString()).apply();render();}}catch(JSONException ignored){}}}
}
